action.mutation:
mutation CreateOperatorHistory($payload: [OperatorHistoryCreatePayloadInput!]!) {
  mutation: createOperatorHistory(payload: $payload) { 
    id
    number
  }
}

mutation UpdateOperatorHistory($payload: [OperatorHistoryUpdatePayloadInput!]!) {
  mutation: updateOperatorHistory(payload: $payload) { 
    id
    number
  }
}

mutation DeleteOperatorHistory($payload: [OperatorHistoryDeletePayloadInput!]!) {
  mutation: deleteOperatorHistory(payload: $payload) { 
    id
    number
  }
}
